/**
 * scoring.ts — Pillar score calculation and result aggregation
 *
 * Takes raw AI findings from vision + text analysis and pagespeed,
 * merges them, calculates weighted overall score, and counts issue types.
 */

// ── Types (mirrored from src/types/index.ts for Deno runtime) ─

export type CroPillar =
  | "value_proposition"
  | "cta_effectiveness"
  | "trust_signals"
  | "visual_hierarchy"
  | "mobile_experience"
  | "content_copy"
  | "page_performance";

export type PageType =
  | "landing"
  | "product"
  | "homepage"
  | "pricing"
  | "signup"
  | "blog"
  | "other";

export type Severity = "critical" | "warning" | "info" | "passed";
export type Effort = "quick" | "moderate" | "significant";

export interface Finding {
  id: string;
  title: string;
  severity: Severity;
  current_state: string;
  recommendation: string;
  ai_suggestion: string;
  is_premium: boolean;
  effort: Effort;
  estimated_lift: string;
  category: string;
}

export interface PillarResult {
  pillar: CroPillar;
  score: number;
  weight: number;
  benchmark: number;
  findings: Finding[];
}

export interface ScoringOutput {
  overall_score: number;
  pillar_results: PillarResult[];
  issues_found: number;
  critical_issues: number;
  warnings: number;
  quick_wins: number;
}

// ── Pillar weights by page type ───────────────────────────────
// Mirrors PAGE_TYPE_WEIGHTS from src/lib/score-utils.ts

const PAGE_TYPE_WEIGHTS: Record<PageType, Record<CroPillar, number>> = {
  landing: {
    value_proposition: 0.20,
    cta_effectiveness: 0.22,
    trust_signals: 0.18,
    visual_hierarchy: 0.10,
    mobile_experience: 0.12,
    content_copy: 0.10,
    page_performance: 0.08,
  },
  product: {
    value_proposition: 0.12,
    cta_effectiveness: 0.18,
    trust_signals: 0.22,
    visual_hierarchy: 0.10,
    mobile_experience: 0.15,
    content_copy: 0.13,
    page_performance: 0.10,
  },
  homepage: {
    value_proposition: 0.22,
    cta_effectiveness: 0.15,
    trust_signals: 0.15,
    visual_hierarchy: 0.15,
    mobile_experience: 0.12,
    content_copy: 0.12,
    page_performance: 0.09,
  },
  pricing: {
    value_proposition: 0.15,
    cta_effectiveness: 0.20,
    trust_signals: 0.22,
    visual_hierarchy: 0.12,
    mobile_experience: 0.10,
    content_copy: 0.13,
    page_performance: 0.08,
  },
  signup: {
    value_proposition: 0.18,
    cta_effectiveness: 0.25,
    trust_signals: 0.20,
    visual_hierarchy: 0.08,
    mobile_experience: 0.15,
    content_copy: 0.08,
    page_performance: 0.06,
  },
  blog: {
    value_proposition: 0.10,
    cta_effectiveness: 0.12,
    trust_signals: 0.08,
    visual_hierarchy: 0.15,
    mobile_experience: 0.15,
    content_copy: 0.25,
    page_performance: 0.15,
  },
  other: {
    value_proposition: 0.15,
    cta_effectiveness: 0.15,
    trust_signals: 0.15,
    visual_hierarchy: 0.14,
    mobile_experience: 0.14,
    content_copy: 0.14,
    page_performance: 0.13,
  },
};

// ── Industry benchmarks ───────────────────────────────────────
// Mirrors INDUSTRY_BENCHMARKS from src/lib/score-utils.ts

const INDUSTRY_BENCHMARKS: Record<CroPillar, number> = {
  value_proposition: 62,
  cta_effectiveness: 55,
  trust_signals: 48,
  visual_hierarchy: 67,
  mobile_experience: 58,
  content_copy: 60,
  page_performance: 72,
};

// ── AI response pillar types ──────────────────────────────────

interface AIPillarResult {
  score: number;
  findings: Finding[];
}

export interface VisionAnalysisResult {
  visual_hierarchy: AIPillarResult;
  cta_effectiveness: AIPillarResult;
  trust_signals: AIPillarResult;
  mobile_experience: AIPillarResult;
}

export interface TextAnalysisResult {
  value_proposition: AIPillarResult;
  content_copy: AIPillarResult;
  // text analysis may also add cta_effectiveness findings — we merge them
  cta_effectiveness?: AIPillarResult;
}

export interface PageSpeedResult {
  score: number;
  findings: Finding[];
}

// ── Core scoring function ─────────────────────────────────────

export function calculateScoringOutput(
  visionResult: VisionAnalysisResult,
  textResult: TextAnalysisResult,
  pageSpeedResult: PageSpeedResult,
  pageType: PageType,
  scanId: string,
): ScoringOutput {
  const weights = PAGE_TYPE_WEIGHTS[pageType] ?? PAGE_TYPE_WEIGHTS.other;

  // Merge CTA findings: vision CTA + any text CTA findings
  const ctaFindings: Finding[] = [
    ...(visionResult.cta_effectiveness?.findings ?? []),
  ];
  if (textResult.cta_effectiveness?.findings) {
    // Avoid duplicate finding IDs by prefixing text-sourced CTA findings
    const textCtaFindings = textResult.cta_effectiveness.findings.map((f) => ({
      ...f,
      id: f.id.startsWith("f_ct_copy") ? f.id : `f_ct_copy_${f.id}`,
    }));
    ctaFindings.push(...textCtaFindings);
  }

  // Average CTA scores from both sources if text analysis included CTA
  let ctaScore = visionResult.cta_effectiveness?.score ?? 50;
  if (textResult.cta_effectiveness?.score !== undefined) {
    ctaScore = Math.round((ctaScore + textResult.cta_effectiveness.score) / 2);
  }

  // Build pillar results array
  const pillarResults: PillarResult[] = [
    {
      pillar: "value_proposition",
      score: clampScore(textResult.value_proposition?.score ?? 50),
      weight: weights.value_proposition,
      benchmark: INDUSTRY_BENCHMARKS.value_proposition,
      findings: deduplicateFindings(textResult.value_proposition?.findings ?? []),
    },
    {
      pillar: "cta_effectiveness",
      score: clampScore(ctaScore),
      weight: weights.cta_effectiveness,
      benchmark: INDUSTRY_BENCHMARKS.cta_effectiveness,
      findings: deduplicateFindings(ctaFindings),
    },
    {
      pillar: "trust_signals",
      score: clampScore(visionResult.trust_signals?.score ?? 50),
      weight: weights.trust_signals,
      benchmark: INDUSTRY_BENCHMARKS.trust_signals,
      findings: deduplicateFindings(visionResult.trust_signals?.findings ?? []),
    },
    {
      pillar: "visual_hierarchy",
      score: clampScore(visionResult.visual_hierarchy?.score ?? 50),
      weight: weights.visual_hierarchy,
      benchmark: INDUSTRY_BENCHMARKS.visual_hierarchy,
      findings: deduplicateFindings(visionResult.visual_hierarchy?.findings ?? []),
    },
    {
      pillar: "mobile_experience",
      score: clampScore(visionResult.mobile_experience?.score ?? 50),
      weight: weights.mobile_experience,
      benchmark: INDUSTRY_BENCHMARKS.mobile_experience,
      findings: deduplicateFindings(visionResult.mobile_experience?.findings ?? []),
    },
    {
      pillar: "content_copy",
      score: clampScore(textResult.content_copy?.score ?? 50),
      weight: weights.content_copy,
      benchmark: INDUSTRY_BENCHMARKS.content_copy,
      findings: deduplicateFindings(textResult.content_copy?.findings ?? []),
    },
    {
      pillar: "page_performance",
      score: clampScore(pageSpeedResult.score),
      weight: weights.page_performance,
      benchmark: INDUSTRY_BENCHMARKS.page_performance,
      findings: deduplicateFindings(pageSpeedResult.findings),
    },
  ];

  // Calculate weighted overall score
  let weightedSum = 0;
  let totalWeight = 0;
  for (const result of pillarResults) {
    weightedSum += result.score * result.weight;
    totalWeight += result.weight;
  }
  const overallScore = totalWeight > 0
    ? Math.round(weightedSum / totalWeight)
    : 0;

  // Count issues across all pillars
  let issuesFound = 0;
  let criticalIssues = 0;
  let warnings = 0;
  let quickWins = 0;

  for (const result of pillarResults) {
    for (const finding of result.findings) {
      if (finding.severity === "critical") {
        issuesFound++;
        criticalIssues++;
      } else if (finding.severity === "warning") {
        issuesFound++;
        warnings++;
      } else if (finding.severity === "info") {
        issuesFound++;
      }
      // "passed" findings don't count as issues
      if (
        finding.effort === "quick" &&
        finding.severity !== "passed" &&
        finding.severity !== "info"
      ) {
        quickWins++;
      }
    }
  }

  return {
    overall_score: clampScore(overallScore),
    pillar_results: pillarResults,
    issues_found: issuesFound,
    critical_issues: criticalIssues,
    warnings,
    quick_wins: quickWins,
  };
}

// ── Helpers ───────────────────────────────────────────────────

function clampScore(score: number): number {
  return Math.max(0, Math.min(100, Math.round(score)));
}

/** Removes findings with duplicate IDs, keeping first occurrence */
function deduplicateFindings(findings: Finding[]): Finding[] {
  const seen = new Set<string>();
  return findings.filter((f) => {
    if (seen.has(f.id)) return false;
    seen.add(f.id);
    return true;
  });
}

/** Validates that a finding object has all required fields */
export function validateFinding(f: unknown): f is Finding {
  if (!f || typeof f !== "object") return false;
  const obj = f as Record<string, unknown>;
  return (
    typeof obj.id === "string" &&
    typeof obj.title === "string" &&
    typeof obj.severity === "string" &&
    ["critical", "warning", "info", "passed"].includes(obj.severity as string) &&
    typeof obj.current_state === "string" &&
    typeof obj.recommendation === "string" &&
    typeof obj.ai_suggestion === "string" &&
    typeof obj.is_premium === "boolean" &&
    typeof obj.effort === "string" &&
    ["quick", "moderate", "significant"].includes(obj.effort as string) &&
    typeof obj.estimated_lift === "string" &&
    typeof obj.category === "string"
  );
}

/** Sanitizes a raw AI finding — fills missing fields with safe defaults */
export function sanitizeFinding(f: Record<string, unknown>, fallbackId: string): Finding {
  const severities: Severity[] = ["critical", "warning", "info", "passed"];
  const efforts: Effort[] = ["quick", "moderate", "significant"];

  const rawSeverity = f.severity as string;
  const rawEffort = f.effort as string;

  // Map AI response effort values to our Effort type
  // The AI prompt uses "quick" but let's also handle "quick_win" if AI slips
  let effort: Effort = "moderate";
  if (rawEffort === "quick" || rawEffort === "quick_win") effort = "quick";
  else if (rawEffort === "significant") effort = "significant";
  else if (efforts.includes(rawEffort as Effort)) effort = rawEffort as Effort;

  return {
    id: typeof f.id === "string" && f.id ? f.id : fallbackId,
    title: typeof f.title === "string" ? f.title.slice(0, 120) : "Untitled finding",
    severity: severities.includes(rawSeverity as Severity)
      ? (rawSeverity as Severity)
      : "info",
    current_state: typeof f.current_state === "string"
      ? f.current_state
      : "No details available.",
    recommendation: typeof f.recommendation === "string"
      ? f.recommendation
      : "Review and optimize this element.",
    ai_suggestion: typeof f.ai_suggestion === "string"
      ? f.ai_suggestion
      : "No AI suggestion generated.",
    is_premium: typeof f.is_premium === "boolean" ? f.is_premium : false,
    effort,
    estimated_lift: typeof f.estimated_lift === "string"
      ? f.estimated_lift
      : "0-1% conversion lift",
    category: typeof f.category === "string" ? f.category : "Design",
  };
}

/**
 * analyze-url — Edge Function (Orchestrator)
 *
 * Full CRO audit pipeline for a given URL.
 *
 * Pipeline:
 *   1. Auth + scan limit check
 *   2. Create scan record (status: analyzing)
 *   3. Screenshot + DOM scrape (Railway service or dev fallback)
 *   4. Upload screenshot to Supabase Storage
 *   5. AI Vision Analysis (Claude + screenshot)
 *   6. AI Text Analysis (Claude + DOM content)
 *   7. PageSpeed Analysis (Google API)
 *   8. Score + Save (insert scan_results, update scan)
 *   9. Return scan ID
 *
 * Required env vars:
 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 *   ANTHROPIC_API_KEY
 *   SCREENSHOT_SERVICE_URL (Railway service) — optional in dev
 *   SCREENSHOT_SERVICE_API_KEY — required if service URL is set
 *   PAGESPEED_API_KEY — Google Cloud API key
 *   SCREENSHOTONE_ACCESS_KEY — dev fallback screenshot service
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildVisionPrompt, buildTextPrompt, PageType } from "./prompts.ts";
import {
  calculateScoringOutput,
  sanitizeFinding,
  VisionAnalysisResult,
  TextAnalysisResult,
  PageSpeedResult,
  Finding,
} from "./scoring.ts";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function corsResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── DOM data shape from screenshot service ────────────────────

interface DomData {
  headings: string[];
  cta_buttons: string[];
  images: Array<{ src: string; alt: string }>;
  meta_description: string;
  body_text: string;
  links: Array<{ text: string; href: string }>;
  forms: number;
  testimonials: string[];
  trust_badges: string[];
}

interface ScreenshotServiceResponse {
  screenshot_base64: string;
  dom_data: DomData;
  page_title: string;
  favicon_url: string;
}

// ── Main handler ──────────────────────────────────────────────

serve(async (req: Request) => {
  // Preflight
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return corsResponse({ error: "Method not allowed" }, 405);
  }

  // ── 1. Auth ─────────────────────────────────────────────────
  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return corsResponse({ error: "Missing authorization header" }, 401);
  }
  const token = authHeader.replace("Bearer ", "").trim();

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
  if (!user || authError) {
    return corsResponse({ error: "Unauthorized" }, 401);
  }

  // ── 2. Parse request body ────────────────────────────────────
  let url: string;
  let pageType: PageType;
  try {
    const body = await req.json();
    url = body.url;
    pageType = body.page_type ?? "other";
    if (!url || typeof url !== "string") {
      return corsResponse({ error: "url is required" }, 400);
    }
    // Normalize URL
    if (!url.startsWith("http://") && !url.startsWith("https://")) {
      url = `https://${url}`;
    }
    new URL(url); // validate format — throws if invalid
  } catch (_e) {
    return corsResponse({ error: "Invalid request body or URL" }, 400);
  }

  // ── 3. Check scan limit ──────────────────────────────────────
  const { data: allowed, error: limitError } = await supabase.rpc(
    "increment_scan_usage",
    { user_uuid: user.id },
  );
  if (limitError || !allowed) {
    return corsResponse(
      { error: "Scan limit reached. Upgrade your plan to continue." },
      429,
    );
  }

  // ── 4. Create scan record ────────────────────────────────────
  const { data: scan, error: scanInsertError } = await supabase
    .from("scans")
    .insert({
      user_id: user.id,
      url,
      page_type: pageType,
      status: "analyzing",
      device: "both",
    })
    .select("id")
    .single();

  if (scanInsertError || !scan) {
    console.error("Failed to create scan record:", scanInsertError);
    return corsResponse({ error: "Failed to initiate scan" }, 500);
  }

  const scanId: string = scan.id;

  // All subsequent errors must update scan status to failed
  const failScan = async (message: string) => {
    await supabase
      .from("scans")
      .update({ status: "failed", error_message: message })
      .eq("id", scanId);
  };

  try {
    // ── 5. Screenshot + Scrape ─────────────────────────────────
    let screenshotData: ScreenshotServiceResponse;
    try {
      screenshotData = await captureScreenshot(url);
    } catch (e) {
      const msg = e instanceof Error ? e.message : "Screenshot capture failed";
      await failScan(msg);
      return corsResponse({ error: msg }, 500);
    }

    // ── 6. Upload screenshot ───────────────────────────────────
    let screenshotUrl: string | null = null;
    if (screenshotData.screenshot_base64) {
      try {
        screenshotUrl = await uploadScreenshot(
          supabase,
          screenshotData.screenshot_base64,
          scanId,
        );
      } catch (e) {
        // Non-fatal — scan continues without screenshot
        console.warn("Screenshot upload failed:", e);
      }
    }

    // Update scan with page metadata from screenshot service
    await supabase
      .from("scans")
      .update({
        page_title: screenshotData.page_title || null,
        favicon_url: screenshotData.favicon_url || null,
        screenshot_url: screenshotUrl,
      })
      .eq("id", scanId);

    // ── 7. AI Vision Analysis ──────────────────────────────────
    let visionResult: VisionAnalysisResult;
    try {
      visionResult = await runVisionAnalysis(
        screenshotData.screenshot_base64,
        pageType,
      );
    } catch (e) {
      const msg = e instanceof Error ? e.message : "AI vision analysis failed";
      await failScan(msg);
      return corsResponse({ error: msg }, 500);
    }

    // ── 8. AI Text Analysis ────────────────────────────────────
    let textResult: TextAnalysisResult;
    try {
      textResult = await runTextAnalysis(screenshotData.dom_data, pageType);
    } catch (e) {
      const msg = e instanceof Error ? e.message : "AI text analysis failed";
      await failScan(msg);
      return corsResponse({ error: msg }, 500);
    }

    // ── 9. PageSpeed Analysis ──────────────────────────────────
    let pageSpeedResult: PageSpeedResult;
    try {
      pageSpeedResult = await runPageSpeedAnalysis(url);
    } catch (e) {
      // Non-fatal — use fallback score
      console.warn("PageSpeed analysis failed, using fallback:", e);
      pageSpeedResult = buildPageSpeedFallback();
    }

    // ── 10. Score + Save ───────────────────────────────────────
    const scoring = calculateScoringOutput(
      visionResult,
      textResult,
      pageSpeedResult,
      pageType,
      scanId,
    );

    // Insert one row per pillar into scan_results
    const scanResultRows = scoring.pillar_results.map((pr) => ({
      scan_id: scanId,
      pillar: pr.pillar,
      score: pr.score,
      weight: pr.weight,
      benchmark: pr.benchmark,
      findings: pr.findings,
    }));

    const { error: resultsError } = await supabase
      .from("scan_results")
      .insert(scanResultRows);

    if (resultsError) {
      console.error("Failed to insert scan_results:", resultsError);
      await failScan("Failed to save analysis results");
      return corsResponse({ error: "Failed to save results" }, 500);
    }

    // Update scan to completed
    const { error: updateError } = await supabase
      .from("scans")
      .update({
        status: "completed",
        overall_score: scoring.overall_score,
        issues_found: scoring.issues_found,
        critical_issues: scoring.critical_issues,
        warnings: scoring.warnings,
        quick_wins: scoring.quick_wins,
        completed_at: new Date().toISOString(),
      })
      .eq("id", scanId);

    if (updateError) {
      console.error("Failed to update scan status:", updateError);
      // Results are saved — don't fail the whole scan
    }

    return corsResponse({ scan_id: scanId, overall_score: scoring.overall_score });
  } catch (error) {
    const msg = error instanceof Error ? error.message : "Unexpected error during scan";
    console.error("Unexpected scan error:", error);
    await failScan(msg);
    return corsResponse({ error: "Scan failed due to an unexpected error" }, 500);
  }
});

// ── Screenshot + Scrape ───────────────────────────────────────

async function captureScreenshot(url: string): Promise<ScreenshotServiceResponse> {
  const serviceUrl = Deno.env.get("SCREENSHOT_SERVICE_URL");

  if (serviceUrl) {
    // Production: Railway Puppeteer service
    const apiKey = Deno.env.get("SCREENSHOT_SERVICE_API_KEY") ?? "";
    const res = await fetch(`${serviceUrl}/screenshot`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-API-Key": apiKey,
      },
      body: JSON.stringify({ url, device: "desktop" }),
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Screenshot service error ${res.status}: ${text.slice(0, 200)}`);
    }

    return await res.json() as ScreenshotServiceResponse;
  }

  // Dev fallback: ScreenshotOne API + fetch DOM ourselves
  console.warn(
    "SCREENSHOT_SERVICE_URL not set — using dev fallback (ScreenshotOne + fetch).",
  );
  return await devFallbackCapture(url);
}

async function devFallbackCapture(url: string): Promise<ScreenshotServiceResponse> {
  const accessKey = Deno.env.get("SCREENSHOTONE_ACCESS_KEY");

  let screenshotBase64 = "";
  if (accessKey) {
    try {
      // ScreenshotOne free tier — returns base64 image
      const params = new URLSearchParams({
        access_key: accessKey,
        url,
        full_page: "true",
        viewport_width: "1280",
        viewport_height: "900",
        format: "jpg",
        image_quality: "80",
        response_type: "json",
      });
      const ssRes = await fetch(
        `https://api.screenshotone.com/take?${params.toString()}`,
      );
      if (ssRes.ok) {
        const ssJson = await ssRes.json();
        screenshotBase64 = ssJson.screenshot ?? "";
      }
    } catch (e) {
      console.warn("ScreenshotOne fallback failed:", e);
    }
  }

  // Fetch raw HTML for DOM scraping
  const domData = await scrapeDomFromHtml(url);

  return {
    screenshot_base64: screenshotBase64,
    dom_data: domData.domData,
    page_title: domData.pageTitle,
    favicon_url: domData.faviconUrl,
  };
}

// ── Lightweight HTML scraper (dev fallback) ───────────────────

async function scrapeDomFromHtml(url: string): Promise<{
  domData: DomData;
  pageTitle: string;
  faviconUrl: string;
}> {
  let html = "";
  try {
    const res = await fetch(url, {
      headers: {
        "User-Agent":
          "Mozilla/5.0 (compatible; CROBOT/1.0; +https://convertscn.com)",
        "Accept": "text/html,application/xhtml+xml",
      },
      signal: AbortSignal.timeout(15_000),
    });
    if (res.ok) {
      html = await res.text();
    }
  } catch (e) {
    console.warn("HTML fetch failed:", e);
    // Return empty DOM — AI will flag missing data as findings
  }

  return parseHtml(html, url);
}

function parseHtml(
  html: string,
  baseUrl: string,
): { domData: DomData; pageTitle: string; faviconUrl: string } {
  // Extract title
  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  const pageTitle = titleMatch ? decodeHtmlEntities(titleMatch[1].trim()) : "";

  // Extract favicon
  const faviconMatch = html.match(
    /<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i,
  ) ?? html.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["'](?:shortcut )?icon["']/i);
  let faviconUrl = "";
  if (faviconMatch) {
    try {
      faviconUrl = new URL(faviconMatch[1], baseUrl).toString();
    } catch (_) {
      faviconUrl = faviconMatch[1];
    }
  }

  // Extract meta description
  const metaMatch = html.match(
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i,
  ) ?? html.match(
    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i,
  );
  const metaDescription = metaMatch ? decodeHtmlEntities(metaMatch[1]) : "";

  // Extract headings h1-h4
  const headings: string[] = [];
  const headingRegex = /<h([1-4])[^>]*>([\s\S]*?)<\/h\1>/gi;
  let hMatch;
  while ((hMatch = headingRegex.exec(html)) !== null && headings.length < 20) {
    const text = stripTags(hMatch[2]).trim();
    if (text) headings.push(text);
  }

  // Extract buttons and links with CTA-like text
  const ctaButtons: string[] = [];
  const ctaKeywords = /\b(get|start|try|sign|join|buy|shop|order|book|schedule|download|learn|see|watch|explore|discover|request|contact|subscribe)\b/i;
  const buttonRegex = /<(?:button|a)[^>]*>([\s\S]*?)<\/(?:button|a)>/gi;
  let btnMatch;
  while ((btnMatch = buttonRegex.exec(html)) !== null && ctaButtons.length < 15) {
    const text = stripTags(btnMatch[1]).trim();
    if (text && text.length < 60 && ctaKeywords.test(text)) {
      ctaButtons.push(text);
    }
  }

  // Extract images
  const images: Array<{ src: string; alt: string }> = [];
  const imgRegex = /<img[^>]+>/gi;
  let imgMatch;
  while ((imgMatch = imgRegex.exec(html)) !== null && images.length < 20) {
    const srcMatch = imgMatch[0].match(/src=["']([^"']+)["']/i);
    const altMatch = imgMatch[0].match(/alt=["']([^"']*)["']/i);
    if (srcMatch) {
      images.push({
        src: srcMatch[1],
        alt: altMatch ? altMatch[1] : "",
      });
    }
  }

  // Extract links
  const links: Array<{ text: string; href: string }> = [];
  const linkRegex = /<a[^>]+href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let linkMatch;
  while ((linkMatch = linkRegex.exec(html)) !== null && links.length < 30) {
    const text = stripTags(linkMatch[2]).trim();
    if (text && text.length < 80) {
      links.push({ text, href: linkMatch[1] });
    }
  }

  // Count forms
  const forms = (html.match(/<form[^>]*>/gi) ?? []).length;

  // Heuristic: extract testimonial-like text blocks (blockquote or q tags)
  const testimonials: string[] = [];
  const quoteRegex = /<(?:blockquote|q)[^>]*>([\s\S]*?)<\/(?:blockquote|q)>/gi;
  let qMatch;
  while ((qMatch = quoteRegex.exec(html)) !== null && testimonials.length < 5) {
    const text = stripTags(qMatch[1]).trim();
    if (text && text.length > 30) testimonials.push(text.slice(0, 300));
  }

  // Extract body text (strip scripts, styles, nav, footer first)
  let bodyText = html
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<nav[\s\S]*?<\/nav>/gi, "")
    .replace(/<footer[\s\S]*?<\/footer>/gi, "")
    .replace(/<header[\s\S]*?<\/header>/gi, "");
  bodyText = stripTags(bodyText).replace(/\s+/g, " ").trim();

  // Detect trust badges from common keywords
  const trustBadges: string[] = [];
  const badgeKeywords = [
    "SSL", "GDPR", "SOC 2", "ISO", "PCI", "HIPAA", "BBB",
    "Trustpilot", "G2", "Capterra", "Product Hunt", "4.8", "4.9", "5.0",
    "money-back guarantee", "100% satisfaction", "secure checkout",
    "verified", "certified", "award",
  ];
  for (const kw of badgeKeywords) {
    if (html.toLowerCase().includes(kw.toLowerCase())) {
      trustBadges.push(kw);
    }
  }

  return {
    domData: {
      headings,
      cta_buttons: ctaButtons,
      images,
      meta_description: metaDescription,
      body_text: bodyText,
      links,
      forms,
      testimonials,
      trust_badges: trustBadges,
    },
    pageTitle,
    faviconUrl,
  };
}

// ── Screenshot Upload ─────────────────────────────────────────

async function uploadScreenshot(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  base64Data: string,
  scanId: string,
): Promise<string> {
  // Decode base64 to Uint8Array
  const binaryStr = atob(base64Data);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) {
    bytes[i] = binaryStr.charCodeAt(i);
  }

  const path = `${scanId}/screenshot.jpg`;
  const { error } = await supabase.storage
    .from("screenshots")
    .upload(path, bytes, {
      contentType: "image/jpeg",
      upsert: true,
    });

  if (error) throw new Error(`Storage upload failed: ${error.message}`);

  const { data } = supabase.storage.from("screenshots").getPublicUrl(path);
  return data.publicUrl;
}

// ── AI Vision Analysis ────────────────────────────────────────

async function runVisionAnalysis(
  screenshotBase64: string,
  pageType: PageType,
): Promise<VisionAnalysisResult> {
  const anthropicKey = Deno.env.get("ANTHROPIC_API_KEY");
  if (!anthropicKey) throw new Error("ANTHROPIC_API_KEY is not configured");

  const systemPrompt = buildVisionPrompt(pageType);

  const messageContent: unknown[] = screenshotBase64
    ? [
        {
          type: "image",
          source: {
            type: "base64",
            media_type: "image/jpeg",
            data: screenshotBase64,
          },
        },
        {
          type: "text",
          text: "Analyze this page screenshot and return the CRO analysis JSON.",
        },
      ]
    : [
        {
          type: "text",
          text: "No screenshot was available. Return JSON with score 50 for all pillars and findings noting that a screenshot could not be captured for visual analysis.",
        },
      ];

  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": anthropicKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: "claude-sonnet-4-20250514",
      max_tokens: 4096,
      system: systemPrompt,
      messages: [{ role: "user", content: messageContent }],
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Anthropic API error ${res.status}: ${text.slice(0, 300)}`);
  }

  const data = await res.json();
  const rawText: string = data.content?.[0]?.text ?? "{}";

  return parseAndSanitizeVisionResult(rawText);
}

// ── AI Text Analysis ──────────────────────────────────────────

async function runTextAnalysis(
  domData: DomData,
  pageType: PageType,
): Promise<TextAnalysisResult> {
  const anthropicKey = Deno.env.get("ANTHROPIC_API_KEY");
  if (!anthropicKey) throw new Error("ANTHROPIC_API_KEY is not configured");

  const systemPrompt = buildTextPrompt(
    pageType,
    domData.headings,
    domData.cta_buttons,
    domData.meta_description,
    domData.body_text,
    domData.forms,
    domData.testimonials,
    domData.trust_badges,
    domData.links,
  );

  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": anthropicKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: "claude-sonnet-4-20250514",
      max_tokens: 4096,
      system: systemPrompt,
      messages: [
        {
          role: "user",
          content: "Analyze the page content provided in the system prompt and return the CRO analysis JSON.",
        },
      ],
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Anthropic API error ${res.status}: ${text.slice(0, 300)}`);
  }

  const data = await res.json();
  const rawText: string = data.content?.[0]?.text ?? "{}";

  return parseAndSanitizeTextResult(rawText);
}

// ── PageSpeed Analysis ────────────────────────────────────────

async function runPageSpeedAnalysis(url: string): Promise<PageSpeedResult> {
  const apiKey = Deno.env.get("PAGESPEED_API_KEY");
  if (!apiKey) {
    console.warn("PAGESPEED_API_KEY not set — using fallback performance score");
    return buildPageSpeedFallback();
  }

  // Call the pagespeed edge function via internal Supabase function invocation
  // Alternatively, call the Google API directly here
  const psUrl = new URL("https://www.googleapis.com/pagespeedonline/v5/runPagespeed");
  psUrl.searchParams.set("url", url);
  psUrl.searchParams.set("key", apiKey);
  psUrl.searchParams.set("strategy", "mobile");
  psUrl.searchParams.set("category", "performance");

  const res = await fetch(psUrl.toString(), {
    signal: AbortSignal.timeout(30_000),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`PageSpeed API error ${res.status}: ${text.slice(0, 200)}`);
  }

  const psData = await res.json();
  return parsePageSpeedData(psData);
}

function parsePageSpeedData(psData: Record<string, unknown>): PageSpeedResult {
  // deno-lint-ignore no-explicit-any
  const audits = (psData as any)?.lighthouseResult?.audits ?? {};
  // deno-lint-ignore no-explicit-any
  const categories = (psData as any)?.lighthouseResult?.categories ?? {};

  const performanceScore = Math.round(
    (categories.performance?.score ?? 0.5) * 100,
  );

  // Extract Core Web Vitals in milliseconds
  const lcpMs: number = audits["largest-contentful-paint"]?.numericValue ?? 0;
  const clsVal: number = audits["cumulative-layout-shift"]?.numericValue ?? 0;
  const tbtMs: number = audits["total-blocking-time"]?.numericValue ?? 0;
  const fcpMs: number = audits["first-contentful-paint"]?.numericValue ?? 0;
  const ttfbMs: number = audits["server-response-time"]?.numericValue ?? 0;
  const speedIndexMs: number = audits["speed-index"]?.numericValue ?? 0;

  const findings: Finding[] = [];

  // LCP findings
  if (lcpMs > 0) {
    const lcpSec = (lcpMs / 1000).toFixed(1);
    if (lcpMs > 4000) {
      findings.push(buildPerfFinding(
        "f_pp_lcp",
        `LCP (Largest Contentful Paint) is critically slow at ${lcpSec}s`,
        "critical",
        `Your LCP is ${lcpSec}s — Google classifies anything above 4.0s as 'Poor'. This is the single biggest drag on both your SEO rankings and conversion rate. Users see a blank/incomplete page for ${lcpSec} seconds before your primary content renders.`,
        "Identify your LCP element (usually the hero image). Serve it in WebP format, use <link rel='preload'> in <head>, and ensure it's not blocked by render-blocking resources.",
        `1. Add <link rel="preload" as="image" href="hero.webp"> to <head>\n2. Convert hero to WebP (60-80% smaller than PNG/JPG)\n3. Set explicit width/height on the hero element to prevent layout shift\n4. Remove any render-blocking CSS above the fold`,
        false,
        "moderate",
        "2-5% conversion lift",
        "Technical",
      ));
    } else if (lcpMs > 2500) {
      findings.push(buildPerfFinding(
        "f_pp_lcp",
        `LCP needs improvement at ${lcpSec}s (good threshold: 2.5s)`,
        "warning",
        `Your LCP is ${lcpSec}s — Google's 'Needs Improvement' range is 2.5-4.0s. Your hero content takes ${lcpSec} seconds to appear, which increases bounce rate by approximately ${Math.round((lcpMs - 2500) / 100)}%.`,
        "Optimize your LCP element: convert to WebP, add preload hint, and eliminate render-blocking resources above the fold.",
        `Add to <head>: <link rel="preload" as="image" href="hero.webp">\nConvert hero image to WebP format — typical savings: 60-80% file size reduction`,
        false,
        "moderate",
        "1-2% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(buildPerfFinding(
        "f_pp_lcp",
        `Good LCP score: ${lcpSec}s (under 2.5s threshold)`,
        "passed",
        `Your LCP of ${lcpSec}s is within Google's 'Good' range (< 2.5s). Primary content renders quickly, minimizing abandonment from slow loads.`,
        "Maintain this performance. Monitor after adding new hero images or scripts.",
        "No changes needed — LCP is performing well.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // CLS findings
  if (clsVal > 0) {
    if (clsVal > 0.25) {
      findings.push(buildPerfFinding(
        "f_pp_cls",
        `CLS (Cumulative Layout Shift) is critically high at ${clsVal.toFixed(3)}`,
        "critical",
        `Your CLS of ${clsVal.toFixed(3)} is in the 'Poor' range (Google threshold: > 0.25). Elements are jumping around visually as the page loads — this is one of the most frustrating user experiences and directly causes mis-clicks on buttons.`,
        "Add explicit width and height attributes to all images and iframes. Reserve space for dynamically injected content (ads, embeds, fonts).",
        `1. Add width/height to all images: <img width="800" height="450" ...>\n2. Add font-display: swap to @font-face declarations\n3. Reserve space for ads: min-height: 250px on ad containers\n4. Avoid inserting content above existing content on page load`,
        false,
        "moderate",
        "1-3% conversion lift",
        "Technical",
      ));
    } else if (clsVal > 0.1) {
      findings.push(buildPerfFinding(
        "f_pp_cls",
        `CLS score needs improvement at ${clsVal.toFixed(3)} (good threshold: 0.1)`,
        "warning",
        `Your CLS of ${clsVal.toFixed(3)} is in the 'Needs Improvement' range. Some elements are shifting during page load — likely images without dimensions or late-loading fonts.`,
        "Add explicit dimensions to images and use font-display: swap to prevent invisible text flashes.",
        `Add width/height attributes to images above the fold. For fonts: add font-display: swap to your @font-face rules.`,
        false,
        "quick",
        "0.5-1% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(buildPerfFinding(
        "f_pp_cls",
        `Good CLS score: ${clsVal.toFixed(3)} (under 0.1 threshold)`,
        "passed",
        `Your CLS of ${clsVal.toFixed(3)} is within Google's 'Good' range. Page elements stay stable during load — no jarring visual jumps.`,
        "Continue setting explicit dimensions on images and reserving space for dynamic content.",
        "No changes needed — layout stability is excellent.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // TBT (proxy for FID/INP) findings
  if (tbtMs > 0) {
    if (tbtMs > 600) {
      findings.push(buildPerfFinding(
        "f_pp_tbt",
        `Total Blocking Time is critically high at ${Math.round(tbtMs)}ms`,
        "critical",
        `Your TBT is ${Math.round(tbtMs)}ms — well above Google's 200ms good threshold. The main thread is blocked for over half a second during load, making the page feel unresponsive. Users who click buttons during this window get no response, causing frustration and abandonment.`,
        "Audit your JavaScript bundles. Remove unused code, defer non-critical scripts, and break up long tasks (>50ms) into smaller chunks.",
        `1. Run: npx bundlesize to identify large bundles\n2. Add defer/async to non-critical scripts\n3. Use dynamic import() for below-fold components\n4. Remove unused JavaScript with tree-shaking\nTarget: get TBT under 200ms`,
        true,
        "significant",
        "1-3% conversion lift",
        "Technical",
      ));
    } else if (tbtMs > 200) {
      findings.push(buildPerfFinding(
        "f_pp_tbt",
        `Total Blocking Time needs improvement at ${Math.round(tbtMs)}ms`,
        "warning",
        `Your TBT of ${Math.round(tbtMs)}ms is in the 'Needs Improvement' range (good: < 200ms). JavaScript is blocking the main thread longer than optimal.`,
        "Defer non-critical third-party scripts and audit your JavaScript for unused code.",
        `Add defer attribute to analytics and chat scripts. Load third-party widgets only after user interaction (first scroll or click).`,
        false,
        "moderate",
        "0.5-1% conversion lift",
        "Technical",
      ));
    }
  }

  // TTFB findings
  if (ttfbMs > 800) {
    findings.push(buildPerfFinding(
      "f_pp_ttfb",
      `Server response time (TTFB) is slow at ${Math.round(ttfbMs)}ms`,
      ttfbMs > 1800 ? "critical" : "warning",
      `Time to First Byte is ${Math.round(ttfbMs)}ms — Google's good threshold is 800ms. Your server takes ${(ttfbMs / 1000).toFixed(1)} seconds just to start sending data. This delays everything downstream.`,
      "Use a CDN (Cloudflare, Vercel Edge) to serve cached responses closer to users. Optimize server-side rendering or database queries if TTFB is high on all pages.",
      `1. Enable Cloudflare or Vercel Edge Caching\n2. Set Cache-Control headers: max-age=3600 for static assets\n3. If on a shared host, upgrade to dedicated or CDN-backed infrastructure\n4. Run EXPLAIN ANALYZE on slow DB queries`,
      true,
      "significant",
      "1-2% conversion lift",
      "Technical",
    ));
  }

  // Speed Index
  if (speedIndexMs > 3400) {
    findings.push(buildPerfFinding(
      "f_pp_si",
      `Speed Index is high at ${(speedIndexMs / 1000).toFixed(1)}s — page feels slow to fill`,
      "warning",
      `Speed Index of ${(speedIndexMs / 1000).toFixed(1)}s measures how quickly content is visually complete. Above 3.4s means users see a partially empty page for an extended period, which signals poor quality.`,
      "Prioritize above-the-fold content rendering. Use SSR or SSG where possible, and eliminate render-blocking resources.",
      `Use critical CSS inlining for above-fold styles. Remove render-blocking fonts with font-display: swap. Aim for Speed Index under 3.4s.`,
      true,
      "moderate",
      "0.5-1% conversion lift",
      "Technical",
    ));
  }

  // If we have few findings, pad with a general performance note
  if (findings.length < 2) {
    findings.push(buildPerfFinding(
      "f_pp_gen",
      "Page performance is within acceptable range",
      "info",
      `Overall PageSpeed score is ${performanceScore}/100. Core Web Vitals are within acceptable ranges for most users.`,
      "Continue monitoring performance as you add new features. Run Lighthouse audits monthly.",
      "Set up automated Lighthouse CI to catch performance regressions in your deployment pipeline.",
      false,
      "quick",
      "0%",
      "Technical",
    ));
  }

  return { score: performanceScore, findings };
}

function buildPerfFinding(
  id: string,
  title: string,
  severity: "critical" | "warning" | "info" | "passed",
  current_state: string,
  recommendation: string,
  ai_suggestion: string,
  is_premium: boolean,
  effort: "quick" | "moderate" | "significant",
  estimated_lift: string,
  category: string,
): Finding {
  return {
    id,
    title,
    severity,
    current_state,
    recommendation,
    ai_suggestion,
    is_premium,
    effort,
    estimated_lift,
    category,
  };
}

function buildPageSpeedFallback(): PageSpeedResult {
  return {
    score: 65,
    findings: [
      buildPerfFinding(
        "f_pp_fallback",
        "PageSpeed data unavailable — using estimated score",
        "info",
        "Google PageSpeed Insights API was not available during this scan. Performance score is estimated at 65/100 (industry average).",
        "Configure PAGESPEED_API_KEY to enable real PageSpeed analysis in future scans.",
        "Add your Google Cloud API key as PAGESPEED_API_KEY in Supabase Edge Function secrets.",
        false,
        "quick",
        "0%",
        "Technical",
      ),
    ],
  };
}

// ── AI Response Parsers ───────────────────────────────────────

function extractJsonFromText(text: string): string {
  // Strip markdown code blocks if present
  const codeBlockMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) return codeBlockMatch[1].trim();

  // Find first { and last }
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start !== -1 && end !== -1 && end > start) {
    return text.slice(start, end + 1);
  }

  return text.trim();
}

function parseAndSanitizeVisionResult(rawText: string): VisionAnalysisResult {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(extractJsonFromText(rawText));
  } catch (_e) {
    console.error("Failed to parse vision AI response:", rawText.slice(0, 500));
    // Return safe defaults
    return buildDefaultVisionResult();
  }

  return {
    visual_hierarchy: sanitizePillarResult(
      parsed.visual_hierarchy as Record<string, unknown>,
      "vh",
    ),
    cta_effectiveness: sanitizePillarResult(
      parsed.cta_effectiveness as Record<string, unknown>,
      "ct",
    ),
    trust_signals: sanitizePillarResult(
      parsed.trust_signals as Record<string, unknown>,
      "ts",
    ),
    mobile_experience: sanitizePillarResult(
      parsed.mobile_experience as Record<string, unknown>,
      "me",
    ),
  };
}

function parseAndSanitizeTextResult(rawText: string): TextAnalysisResult {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(extractJsonFromText(rawText));
  } catch (_e) {
    console.error("Failed to parse text AI response:", rawText.slice(0, 500));
    return buildDefaultTextResult();
  }

  return {
    value_proposition: sanitizePillarResult(
      parsed.value_proposition as Record<string, unknown>,
      "vp",
    ),
    content_copy: sanitizePillarResult(
      parsed.content_copy as Record<string, unknown>,
      "cc",
    ),
    cta_effectiveness: parsed.cta_effectiveness
      ? sanitizePillarResult(
          parsed.cta_effectiveness as Record<string, unknown>,
          "ct_copy",
        )
      : undefined,
  };
}

function sanitizePillarResult(
  raw: Record<string, unknown> | undefined,
  prefix: string,
): { score: number; findings: Finding[] } {
  if (!raw || typeof raw !== "object") {
    return { score: 50, findings: [] };
  }

  const score = typeof raw.score === "number"
    ? Math.max(0, Math.min(100, Math.round(raw.score)))
    : 50;

  const rawFindings = Array.isArray(raw.findings) ? raw.findings : [];
  const findings: Finding[] = rawFindings
    .filter((f): f is Record<string, unknown> => f !== null && typeof f === "object")
    .map((f, i) =>
      sanitizeFinding(f, `f_${prefix}_${String(i + 1).padStart(2, "0")}`)
    );

  return { score, findings };
}

function buildDefaultVisionResult(): VisionAnalysisResult {
  const defaultPillar = { score: 50, findings: [] };
  return {
    visual_hierarchy: defaultPillar,
    cta_effectiveness: defaultPillar,
    trust_signals: defaultPillar,
    mobile_experience: defaultPillar,
  };
}

function buildDefaultTextResult(): TextAnalysisResult {
  const defaultPillar = { score: 50, findings: [] };
  return {
    value_proposition: defaultPillar,
    content_copy: defaultPillar,
  };
}

// ── HTML Utilities ────────────────────────────────────────────

function stripTags(html: string): string {
  return html.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").trim();
}

function decodeHtmlEntities(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'");
}

/**
 * pagespeed — Edge Function
 *
 * Fetches Google PageSpeed Insights data for a given URL and returns
 * a structured page_performance pillar result.
 *
 * Request body: { url: string; strategy?: 'mobile' | 'desktop' }
 *
 * Response:
 * {
 *   score: number;           // 0-100 overall performance score
 *   findings: Finding[];     // structured CRO findings from metric thresholds
 *   metrics: {
 *     lcp: number;           // Largest Contentful Paint (ms)
 *     cls: number;           // Cumulative Layout Shift (unitless)
 *     tbt: number;           // Total Blocking Time (ms, proxy for FID/INP)
 *     fcp: number;           // First Contentful Paint (ms)
 *     ttfb: number;          // Time to First Byte (ms)
 *     speed_index: number;   // Speed Index (ms)
 *   }
 * }
 *
 * Required env vars:
 *   PAGESPEED_API_KEY — Google Cloud API key with PageSpeed Insights API enabled
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

// ── CORS ──────────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function corsResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── Types ─────────────────────────────────────────────────────

type Severity = "critical" | "warning" | "info" | "passed";
type Effort = "quick" | "moderate" | "significant";

interface Finding {
  id: string;
  title: string;
  severity: Severity;
  current_state: string;
  recommendation: string;
  ai_suggestion: string;
  is_premium: boolean;
  effort: Effort;
  estimated_lift: string;
  category: string;
}

interface PageSpeedMetrics {
  lcp: number;
  cls: number;
  tbt: number;
  fcp: number;
  ttfb: number;
  speed_index: number;
}

interface PageSpeedResponse {
  score: number;
  findings: Finding[];
  metrics: PageSpeedMetrics;
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return corsResponse({ error: "Method not allowed" }, 405);
  }

  // Parse request body
  let url: string;
  let strategy: "mobile" | "desktop" = "mobile";
  try {
    const body = await req.json();
    url = body.url;
    if (body.strategy === "desktop") strategy = "desktop";
    if (!url || typeof url !== "string") {
      return corsResponse({ error: "url is required" }, 400);
    }
    new URL(url); // validate format
  } catch (_e) {
    return corsResponse({ error: "Invalid request body or URL" }, 400);
  }

  const apiKey = Deno.env.get("PAGESPEED_API_KEY");
  if (!apiKey) {
    console.warn("PAGESPEED_API_KEY not configured — returning fallback");
    return corsResponse(buildFallbackResponse());
  }

  // ── Call Google PageSpeed Insights API ─────────────────────
  const psUrl = new URL(
    "https://www.googleapis.com/pagespeedonline/v5/runPagespeed",
  );
  psUrl.searchParams.set("url", url);
  psUrl.searchParams.set("key", apiKey);
  psUrl.searchParams.set("strategy", strategy);
  psUrl.searchParams.set("category", "performance");

  let psData: Record<string, unknown>;
  try {
    const res = await fetch(psUrl.toString(), {
      signal: AbortSignal.timeout(35_000),
    });
    if (!res.ok) {
      const text = await res.text();
      console.error(`PageSpeed API error ${res.status}:`, text.slice(0, 300));
      return corsResponse(buildFallbackResponse(), 200); // soft-fail, don't crash scan
    }
    psData = await res.json();
  } catch (e) {
    console.error("PageSpeed fetch failed:", e);
    return corsResponse(buildFallbackResponse(), 200);
  }

  const result = parsePageSpeedResponse(psData, strategy);
  return corsResponse(result);
});

// ── Parser ────────────────────────────────────────────────────

function parsePageSpeedResponse(
  psData: Record<string, unknown>,
  _strategy: "mobile" | "desktop",
): PageSpeedResponse {
  // deno-lint-ignore no-explicit-any
  const lhResult = (psData as any)?.lighthouseResult ?? {};
  const audits = lhResult?.audits ?? {};
  const categories = lhResult?.categories ?? {};

  const performanceScore = Math.round(
    (categories?.performance?.score ?? 0.5) * 100,
  );

  // Extract raw metric values
  const lcpMs: number = audits["largest-contentful-paint"]?.numericValue ?? 0;
  const clsVal: number = audits["cumulative-layout-shift"]?.numericValue ?? 0;
  const tbtMs: number = audits["total-blocking-time"]?.numericValue ?? 0;
  const fcpMs: number = audits["first-contentful-paint"]?.numericValue ?? 0;
  const ttfbMs: number = audits["server-response-time"]?.numericValue ?? 0;
  const speedIndexMs: number = audits["speed-index"]?.numericValue ?? 0;

  const metrics: PageSpeedMetrics = {
    lcp: Math.round(lcpMs),
    cls: Math.round(clsVal * 1000) / 1000,
    tbt: Math.round(tbtMs),
    fcp: Math.round(fcpMs),
    ttfb: Math.round(ttfbMs),
    speed_index: Math.round(speedIndexMs),
  };

  const findings: Finding[] = [];

  // ── LCP ─────────────────────────────────────────────────────
  if (lcpMs > 0) {
    const lcpSec = (lcpMs / 1000).toFixed(1);
    if (lcpMs > 4000) {
      findings.push(makeFinding(
        "f_pp_lcp",
        `LCP is critically slow at ${lcpSec}s — Google classifies as 'Poor'`,
        "critical",
        `Your Largest Contentful Paint is ${lcpSec}s. Google's 'Poor' threshold is 4.0s and your page exceeds it. The LCP element (likely your hero image or headline) takes ${lcpSec} seconds to appear, directly increasing bounce rate. Research shows every 100ms of LCP delay increases bounce by approximately 1%.`,
        "1. Identify your LCP element with Chrome DevTools Performance tab. 2. Serve it as WebP. 3. Add <link rel='preload'> for the LCP image. 4. Remove render-blocking CSS/JS above the fold.",
        `Add to <head>:\n<link rel="preload" as="image" href="/hero.webp" fetchpriority="high">\n\nConvert your hero image to WebP format (saves 60-80% file size).\n\nSet explicit dimensions on the hero container to eliminate CLS during load:\n<div style="aspect-ratio: 16/9; width: 100%;">`,
        false,
        "moderate",
        "3-6% conversion lift",
        "Technical",
      ));
    } else if (lcpMs > 2500) {
      findings.push(makeFinding(
        "f_pp_lcp",
        `LCP needs improvement at ${lcpSec}s (good: under 2.5s)`,
        "warning",
        `Your LCP is ${lcpSec}s — in Google's 'Needs Improvement' range (2.5s-4.0s). Main content appears ${(lcpMs - 2500)}ms later than Google's recommended threshold. This delays the moment users see your headline and CTA, increasing early abandonment.`,
        "Convert your LCP image to WebP and add a preload hint. Also check for render-blocking stylesheets loaded in <head>.",
        `Add to <head>: <link rel="preload" as="image" href="hero.webp">\nConvert PNG/JPG hero to WebP — average savings: 65% file size.\nTarget: get LCP under 2.5s`,
        false,
        "moderate",
        "1-3% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(makeFinding(
        "f_pp_lcp",
        `LCP is excellent at ${lcpSec}s (well under 2.5s threshold)`,
        "passed",
        `Largest Contentful Paint is ${lcpSec}s — within Google's 'Good' range. Your primary content renders quickly, giving users immediate visual feedback.`,
        "Continue monitoring LCP after adding new hero images or loading new scripts.",
        "No changes needed. Maintain your current image optimization and preloading strategy.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // ── CLS ─────────────────────────────────────────────────────
  if (clsVal >= 0) {
    const clsDisplay = clsVal.toFixed(3);
    if (clsVal > 0.25) {
      findings.push(makeFinding(
        "f_pp_cls",
        `CLS is critically high at ${clsDisplay} — elements jump during load`,
        "critical",
        `Cumulative Layout Shift of ${clsDisplay} is in Google's 'Poor' range (> 0.25). Page elements are jumping significantly during load. This causes mis-clicks — users click on what they think is a button, the page shifts, and they click the wrong element. This directly increases frustration and abandonment.`,
        "Add explicit width and height to ALL images and iframes. Reserve space for late-loading content (ads, embeds). Add font-display: swap to @font-face rules.",
        `Fix all images: <img width="800" height="450" src="..." alt="...">\nFix fonts: add font-display: swap to @font-face\nFix ad containers: set min-height: 250px on ad wrappers\nNever insert content above existing content dynamically`,
        false,
        "moderate",
        "1-3% conversion lift",
        "Technical",
      ));
    } else if (clsVal > 0.1) {
      findings.push(makeFinding(
        "f_pp_cls",
        `CLS needs improvement at ${clsDisplay} (good: under 0.1)`,
        "warning",
        `Layout Shift score of ${clsDisplay} is in Google's 'Needs Improvement' range. Some elements shift during load — likely images missing explicit dimensions or fonts without font-display: swap.`,
        "Add explicit width/height to images above the fold. Add font-display: swap to @font-face declarations.",
        `For images above the fold: always include width and height attributes.\nFor custom fonts: @font-face { font-display: swap; }`,
        false,
        "quick",
        "0.5-1% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(makeFinding(
        "f_pp_cls",
        `CLS is excellent at ${clsDisplay} — layout is stable during load`,
        "passed",
        `Cumulative Layout Shift of ${clsDisplay} is in Google's 'Good' range (< 0.1). Page elements don't jump during load, preventing mis-clicks and frustration.`,
        "Continue setting explicit image dimensions and reserving space for dynamic content.",
        "No changes needed. Layout stability is well-managed.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // ── TBT (proxy for interactivity) ────────────────────────────
  if (tbtMs > 0) {
    const tbtDisplay = Math.round(tbtMs);
    if (tbtMs > 600) {
      findings.push(makeFinding(
        "f_pp_tbt",
        `Total Blocking Time is critically high at ${tbtDisplay}ms`,
        "critical",
        `TBT of ${tbtDisplay}ms means the browser main thread is blocked for over half a second during load. Users who try to interact — click a button, fill a form, or scroll — experience complete unresponsiveness during this window. This is a top cause of 'the site felt slow' complaints even when load time looks acceptable.`,
        "Profile JavaScript with Chrome DevTools. Identify long tasks (>50ms) and break them up. Defer analytics, chat widgets, and non-critical scripts. Use code-splitting for SPA bundles.",
        `1. Add defer to all non-critical scripts:\n   <script defer src="analytics.js"></script>\n2. Load chat widget only after user interaction:\n   window.addEventListener('scroll', loadChat, {once: true})\n3. Use dynamic import() for non-critical React components\n4. Target: reduce TBT under 200ms`,
        true,
        "significant",
        "2-4% conversion lift",
        "Technical",
      ));
    } else if (tbtMs > 200) {
      findings.push(makeFinding(
        "f_pp_tbt",
        `Total Blocking Time needs improvement at ${tbtDisplay}ms`,
        "warning",
        `TBT of ${tbtDisplay}ms is above Google's 200ms good threshold. JavaScript is blocking the main thread during initial load, creating a window of unresponsiveness.`,
        "Defer non-critical third-party scripts and audit for unused JavaScript.",
        `Add defer attribute to analytics and marketing scripts.\nDefer the chat widget until after user first interaction.\nTarget: under 200ms TBT`,
        false,
        "moderate",
        "0.5-1% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(makeFinding(
        "f_pp_tbt",
        `Total Blocking Time is excellent at ${tbtDisplay}ms`,
        "passed",
        `TBT of ${tbtDisplay}ms is well within Google's 'Good' range (< 200ms). The main thread is largely unblocked during load, allowing quick interaction.`,
        "Monitor TBT as you add third-party scripts or expand your JavaScript bundle.",
        "No changes needed. Continue deferring non-critical JavaScript.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // ── TTFB ─────────────────────────────────────────────────────
  if (ttfbMs > 800) {
    const ttfbDisplay = Math.round(ttfbMs);
    const severity: Severity = ttfbMs > 1800 ? "critical" : "warning";
    findings.push(makeFinding(
      "f_pp_ttfb",
      `Server response time (TTFB) is slow at ${ttfbDisplay}ms`,
      severity,
      `Time to First Byte of ${ttfbDisplay}ms means your server takes ${(ttfbMs / 1000).toFixed(1)}s just to start sending data — before any HTML is parsed or resources are loaded. Google's good threshold is 800ms. A slow TTFB delays the entire page load chain.`,
      "Deploy a CDN (Cloudflare, Vercel Edge) for caching. Optimize server-side processing — check for slow database queries or heavy middleware on initial page render.",
      `Quick wins:\n1. Enable Cloudflare proxy — free tier provides global CDN\n2. Add aggressive Cache-Control headers: Cache-Control: public, max-age=3600\n3. Check for database N+1 queries on the page\n4. For Next.js: ensure pages use getStaticProps or ISR where possible`,
      true,
      "significant",
      "1-2% conversion lift",
      "Technical",
    ));
  }

  // ── Speed Index ───────────────────────────────────────────────
  if (speedIndexMs > 3400) {
    const siDisplay = (speedIndexMs / 1000).toFixed(1);
    findings.push(makeFinding(
      "f_pp_si",
      `Speed Index is high at ${siDisplay}s — page fills slowly`,
      "warning",
      `Speed Index of ${siDisplay}s (good: < 3.4s) measures how quickly content is visually complete. A high Speed Index means users see a partially empty page for an extended period, which signals poor quality and erodes trust even before they've read a word.`,
      "Prioritize critical CSS inline, eliminate render-blocking resources, and use SSR or SSG for initial HTML content.",
      `1. Inline critical CSS (above-fold styles) in <style> tags in <head>\n2. Remove any render-blocking @import in CSS files\n3. Use font-display: swap to prevent invisible text\n4. Ensure server-rendered HTML includes visible content (not empty shell for SPAs)`,
      true,
      "moderate",
      "0.5-1% conversion lift",
      "Technical",
    ));
  }

  // ── FCP note if it's slow ────────────────────────────────────
  if (fcpMs > 1800) {
    const fcpDisplay = (fcpMs / 1000).toFixed(1);
    findings.push(makeFinding(
      "f_pp_fcp",
      `First Contentful Paint is slow at ${fcpDisplay}s (good: under 1.8s)`,
      fcpMs > 3000 ? "warning" : "info",
      `FCP of ${fcpDisplay}s — the first moment ANY content appears — is above Google's 1.8s 'Good' threshold. Users see a blank page for ${fcpDisplay}s before anything renders. A blank page increases abandonment by 32% compared to seeing content within 1s.`,
      "Eliminate render-blocking resources. Inline critical CSS. Ensure the server sends HTML with visible content immediately.",
      `Remove render-blocking resources from <head>.\nInline styles for above-the-fold content.\nDefer or async all JavaScript in <head>.\nTarget: FCP under 1.8s`,
      false,
      "moderate",
      "0.5-1% conversion lift",
      "Technical",
    ));
  }

  // If findings is empty (very fast page), add a passed finding
  if (findings.length === 0) {
    findings.push(makeFinding(
      "f_pp_excellent",
      "Page performance is excellent across all Core Web Vitals",
      "passed",
      `All Core Web Vitals are in Google's 'Good' range. PageSpeed score: ${performanceScore}/100. Your page loads fast, stays stable, and responds quickly — a competitive advantage.`,
      "Monitor performance over time with continuous Lighthouse CI. Performance can degrade as features are added.",
      "Set up Lighthouse CI in your GitHub Actions pipeline to catch regressions before they reach production.",
      false,
      "quick",
      "0%",
      "Technical",
    ));
  }

  return { score: performanceScore, findings, metrics };
}

// ── Helper to build a Finding ─────────────────────────────────

function makeFinding(
  id: string,
  title: string,
  severity: Severity,
  current_state: string,
  recommendation: string,
  ai_suggestion: string,
  is_premium: boolean,
  effort: Effort,
  estimated_lift: string,
  category: string,
): Finding {
  return {
    id,
    title,
    severity,
    current_state,
    recommendation,
    ai_suggestion,
    is_premium,
    effort,
    estimated_lift,
    category,
  };
}

// ── Fallback response when API key is missing ─────────────────

function buildFallbackResponse(): PageSpeedResponse {
  return {
    score: 65,
    findings: [
      makeFinding(
        "f_pp_no_api",
        "PageSpeed analysis unavailable — PAGESPEED_API_KEY not configured",
        "info",
        "Google PageSpeed Insights API key is not configured. Performance analysis is estimated at 65/100 (industry average for pages not specifically optimized for performance).",
        "Configure PAGESPEED_API_KEY in Supabase Edge Function secrets to enable real PageSpeed analysis.",
        "Get a free Google Cloud API key at console.cloud.google.com, enable the PageSpeed Insights API, and add it as PAGESPEED_API_KEY in your Supabase project's Edge Function secrets.",
        false,
        "quick",
        "0%",
        "Technical",
      ),
    ],
    metrics: {
      lcp: 0,
      cls: 0,
      tbt: 0,
      fcp: 0,
      ttfb: 0,
      speed_index: 0,
    },
  };
}

